function renderResourceDetail(type,name){
const displayName=name;
name=escapeHtml(name);
  const configs={
    model:{mark:'模',label:'模型配置',note:'模型目录由平台维护；密钥、额度和默认设置只对当前租户生效。',form:`<div class="field"><label>模型</label><input value="${name}" disabled></div><div class="field"><label>租户别名</label><input value="${name}"></div><div class="field span-2"><label>API Key</label><input type="password" value="tenant-secret-key"><small>保存后加密存储，页面不会再次显示明文。</small></div><div class="field"><label>每月 Token 额度</label><input value="30000000"></div><div class="field"><label>调用超时</label><select><option>120 秒</option><option>180 秒</option></select></div>`},
    tool:{mark:'工',label:'工具授权',note:'工具定义由平台提供，这里配置工具分组、当前租户的数据范围和 Agent 使用权限。',form:`<div class="field"><label>工具</label><input value="${name}" disabled></div><div class="field"><label>工具分组</label><select><option>${name.includes('查询')?'数据查询':name.includes('知识')||name.includes('Wiki')?'知识检索':'内容输出'}</option><option>数据查询</option><option>知识检索</option><option>内容输出</option></select></div><div class="field"><label>访问方式</label><select><option>只读</option><option>读写</option></select></div><div class="field"><label>启用状态</label><select><option>已启用</option><option>未启用</option></select></div><div class="field span-2"><label>允许使用的 Agent</label><select><option>指定 Agent</option><option>租户内全部已发布 Agent</option></select></div><div class="field span-2"><label>已授权 Agent</label><input value="经营分析助手，数据查询 Agent"><small>Agent 发布时仍需再次确认工具绑定。</small></div>`},
    mcp:{mark:'连',label:'MCP 连接',note:'连接地址、认证凭据和可访问的数据范围属于当前租户。',form:`<div class="field"><label>MCP 服务</label><input value="${name}" disabled></div><div class="field"><label>连接方式</label><select><option>Streamable HTTP</option><option>STDIO</option></select></div><div class="field span-2"><label>服务地址</label><input value="https://mcp.internal.example.com/${name.includes('GitLab')?'gitlab':'wiki'}"></div><div class="field span-2"><label>访问令牌</label><input type="password" value="tenant-mcp-token"></div><div class="field span-2"><label>开放的 MCP Tool</label><textarea>search\nget_document\nlist_spaces</textarea></div>`},
    skill:{mark:'技',label:'Skill 配置',note:'公共 Skill 可安装到租户；租户私有 Skill 只能被本租户的 Agent 使用。',form:`<div class="field"><label>Skill</label><input value="${name}" disabled></div><div class="field"><label>固定版本</label><select><option>v1.3</option><option>v1.2</option></select></div><div class="field span-2"><label>运行参数</label><textarea>{\n  "output_language": "zh-CN",\n  "require_evidence": true\n}</textarea></div><div class="field span-2"><label>允许使用的 Agent</label><input value="研发协作助手，代码审查 Agent"></div>`},
    user:{mark:'用',label:'用户信息',note:'这是平台登录身份信息；租户成员关系和角色在成员管理页面维护。',form:`<div class="field"><label>姓名</label><input value="${name}"></div><div class="field"><label>用户编码</label><input value="usr_${name==='begincode'?'begincode':name==='begincode-dev'?'begincode_dev':'begincode_user'}" disabled></div><div class="field span-2"><label>企业邮箱</label><input value="${name==='begincode'?'begincode':name==='begincode-dev'?'begincode_dev':'begincode_user'}@company.com"></div><div class="field"><label>登录方式</label><select><option>企业 SSO</option><option>本地账号</option></select></div><div class="field"><label>账号状态</label><select><option>正常</option><option>停用</option></select></div>`},
    member:{mark:'员',label:'成员权限',note:'成员身份属于用户，角色和数据范围属于当前租户。',form:`<div class="field"><label>成员</label><input value="${name}" disabled></div><div class="field"><label>登录账号</label><input value="${name==='begincode'?'begincode':name==='begincode-dev'?'begincode_dev':'begincode_user'}" disabled></div><div class="field"><label>租户角色</label><select><option>${name==='begincode'?'租户管理员':name==='begincode-dev'?'Agent 开发者':'业务使用者'}</option><option>Agent 开发者</option><option>业务使用者</option></select></div><div class="field"><label>状态</label><select><option>正常</option><option>停用</option></select></div><div class="field span-2"><label>数据范围</label><select><option>当前租户全部数据</option><option>仅本人创建的数据</option></select></div>`}
  };
  const c=configs[type];$('#tenant-item-mark').textContent=c.mark;$('#tenant-item-title').textContent=displayName;$('#tenant-item-subtitle').textContent=type==='user'?`${c.label} · 平台账号`:`${c.label} · 研发效能中心`;$('#tenant-item-note').textContent=c.note;$('#tenant-item-form').innerHTML=c.form
}
const defaults={"model": "DeepSeek Chat", "tool": "经营数据查询", "mcp": "企业 Wiki MCP", "skill": "代码审查", "member": "begincode-dev", "user": "begincode"};
const resourceType=document.body.dataset.resourceType;
const requestedName=params.get('name');
const demoIdentities=['begincode','begincode-dev','begincode-user'];
const displayName=['user','member'].includes(resourceType)
  ? (demoIdentities.includes(requestedName)?requestedName:defaults[resourceType])
  : (requestedName||defaults[resourceType]);
renderResourceDetail(resourceType,displayName);
on("#save-tenant-item","click",()=>toast("配置已保存并写入审计记录"));
